  "Opens Spotify in your browser to sign in": {"id": "Membuka Spotify di browser untuk masuk", "ar": "يفتح Spotify في المتصفح لتسجيل الدخول", "bn": "লগইনের জন্য ব্রাউজারে Spotify খোলে", "de": "Öffnet Spotify in deinem Browser zur Anmeldung", "es": "Abre Spotify en tu navegador para iniciar sesión", "fa": "برای ورود، Spotify را در مرورگر باز می‌کند", "fr": "Ouvre Spotify dans votre navigateur pour vous connecter", "he": "פותח את Spotify בדפדפן כדי להתחבר", "hi": "लॉगिन के लिए ब्राउज़र में Spotify खोलता है", "it": "Apre Spotify nel browser per accedere", "ja": "ログインのためにブラウザで Spotify を開きます", "ko": "로그인을 위해 브라우저에서 Spotify를 엽니다", "ms": "Membuka Spotify dalam pelayar untuk log masuk", "nl": "Opent Spotify in je browser om in te loggen", "pl": "Otwiera Spotify w przeglądarce, aby się zalogować", "pt": "Abre o Spotify no navegador para entrar", "ru": "Открывает Spotify в браузере для входа", "sv": "Öppnar Spotify i webbläsaren för att logga in", "th": "เปิด Spotify ในเบราว์เซอร์เพื่อล็อกอิน", "tr": "Giriş yapmak için Spotify'ı tarayıcınızda açar", "uk": "Відкриває Spotify у браузері для входу", "vi": "Mở Spotify trong trình duyệt để đăng nhập", "zh": "在浏览器中打开 Spotify 以登录", "zt": "在瀏覽器中開啟 Spotify 以登入"},
  "Disconnect": {"id": "Putuskan", "ar": "قطع الاتصال", "bn": "সংযোগ বিচ্ছিন্ন করুন", "de": "Trennen", "es": "Desconectar", "fa": "قطع اتصال", "fr": "Déconnecter", "he": "התנתק", "hi": "डिसकनेक्ट करें", "it": "Disconnetti", "ja": "切断", "ko": "연결 해제", "ms": "Putuskan sambungan", "nl": "Verbinding verbreken", "pl": "Rozłącz", "pt": "Desconectar", "ru": "Отключить", "sv": "Koppla från", "th": "ตัดการเชื่อมต่อ", "tr": "Bağlantıyı kes", "uk": "Відключити", "vi": "Ngắt kết nối", "zh": "断开连接", "zt": "斷開連線"},
