  "Symbol / text": {"id": "Simbol / teks", "ar": "رمز / نص", "bn": "চিহ্ন / লেখা", "de": "Symbol / Text", "es": "Símbolo / texto", "fa": "نماد / متن", "fr": "Symbole / texte", "he": "סמל / טקסט", "hi": "प्रतीक / टेक्स्ट", "it": "Simbolo / testo", "ja": "記号 / テキスト", "ko": "기호 / 텍스트", "ms": "Simbol / teks", "nl": "Symbool / tekst", "pl": "Symbol / tekst", "pt": "Símbolo / texto", "ru": "Символ / текст", "th": "สัญลักษณ์ / ข้อความ", "tr": "Simge / metin", "uk": "Символ / текст", "vi": "Ký hiệu / văn bản", "zh": "符号 / 文字", "zt": "符號 / 文字"},
